/* ---------------- SHARED ---------------- */

function SectionHead({ label, title, lede, linkTo, linkLabel }) {
  const { navigate } = useRouter();
  return (
    <div className="grid12" style={{ rowGap: 20, alignItems: "end", marginBottom: "clamp(40px,5vw,68px)" }}>
      <div className="col-span-7">
        <Reveal>
          <p className="label label--accent label-dot" style={{ marginBottom: 22 }}>{label}</p>
          <h2 className="section-title">{title}</h2>
        </Reveal>
      </div>
      <div className="col-span-5" style={{ alignSelf: "end" }}>
        <Reveal delay={80}>
          {lede && <p className="lede" style={{ marginLeft: "auto" }}>{lede}</p>}
          {linkTo && (
            <a href={`#${linkTo}`} onClick={(e)=>{e.preventDefault();navigate(linkTo);}} className="txtlink" style={{ marginTop: 18 }}>
              {linkLabel} <Arrow />
            </a>
          )}
        </Reveal>
      </div>
    </div>
  );
}

